		/** 
		 * Tests creating a new Feature.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Feature");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Feature" );

			try {            
				Feature entity = FeatureService.getFeatureInstance().createFeature( generateNewEntity() );
				thePrimaryKey = entity.getFeatureId();
				LOGGER.info( "-- Successfully created a Feature with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Feature. 
		 */
		public Feature testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Feature" );

			Feature entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Feature with primary key" );
			msg.append( thePrimaryKey );
			
			FeatureFetchOneSummary fetchOneSummary = new FeatureFetchOneSummary( thePrimaryKey );

			try {
				entity = FeatureService.getFeatureInstance().getFeature( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Feature " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Feature.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Feature." );

			StringBuilder msg = new StringBuilder( "Failed to update a Feature : " );        
			Feature entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Feature." );

				// for use later on...
				thePrimaryKey = entity.getFeatureId();

				FeatureService proxy = FeatureService.getFeatureInstance();            
				proxy.updateFeature( entity );   

				LOGGER.info( "-- Successfully saved Feature - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Feature.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Feature." );

			try{
			    Feature entity = testRead(); 
				FeatureService.getFeatureInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Feature with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Feature with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Features.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Features:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Feature : " );        
			List<Feature> collection  = null;

			try {
				// call the static get method on the FeatureService
				collection = FeatureService.getFeatureInstance().getAllFeature();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Feature entity = null;            
					Iterator<Feature> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getFeatureId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/**
		 * Assigns a common log handler for each test class in the suite
		 * @param		handler	Handler
		 * @return		FeatureTest
		 */
		public FeatureTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Feature
		 * 
		 * @return Feature
		 */
		protected Feature generateNewEntity() {
			Feature entity = new Feature( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  DataType.values()[0] );
			
			return( entity );
		}

		//-----------------------------------------------------
		// attributes 
